// Who THIS copy of the app is (DGO-1920). The first copy is `bina-claude`, the tile «קלוד דסקטופ»; a further one
// — an instance, instances/<id>/ generated by platform/manager/instances.py — is told its id in DGO_INSTANCE_ID
// (every container of it carries it), and its tile is named in its own generated manifest. Every name the
// adapter says or acts on (the desktop's container, a notice's source and link, the tile it sends a person
// to) comes from here, so two copies never answer for each other.
import fs from "node:fs";
import path from "node:path";

const OFFICE = process.env.BBOX_REPO_HOST || "/workspace/office";
const TEMPLATE = "bina-claude";

export const APP_ID = process.env.DGO_INSTANCE_ID || TEMPLATE;

// The tile's name as the console shows it: the manifest's own (a module's `name`), read once at start.
export const TILE = tileName(path.join(OFFICE, process.env.DGO_INSTANCE_ID ? "instances" : "apps", APP_ID, "app.json"));

export function tileName(file) {
  try {
    const m = JSON.parse(fs.readFileSync(file, "utf8"));
    const mod = (m.routing || []).map((r) => r && r.module).find((x) => x && x.name);
    return (mod && mod.name) || (m.title && m.title.he) || "קלוד דסקטופ";
  } catch {
    return "קלוד דסקטופ";
  }
}

// The desktop app's container: `<service>-<DEPLOYMENT_NAME>`, the service being the app id's `-desktop`.
export function desktopContainer(env = process.env) {
  return env.BINA_CLAUDE_DESKTOP_CONTAINER || `${APP_ID}-desktop-${env.DEPLOYMENT_NAME || "bina-deployment"}`;
}
